// Fixture batch 088: edge directions of extrudes, a revolve, a fillet, a chamfer and a hole. Generated by tools/fixtures/gen-batch-088.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function round6(v) returns array
{
    return [roundToPrecision(v[0] / millimeter, 6), roundToPrecision(v[1] / millimeter, 6), roundToPrecision(v[2] / millimeter, 6)];
}

function dir6(v) returns array
{
    return [roundToPrecision(v[0], 6), roundToPrecision(v[1], 6), roundToPrecision(v[2], 6)];
}

// Every edge of a body: three points along it in its own order and its direction at its start.
function edgeDirections(context is Context, body is Query) returns array
{
    var out = [];
    for (var edge in evaluateQuery(context, qOwnedByBody(body, EntityType.EDGE)))
    {
        const lines = evEdgeTangentLines(context, { "edge" : edge, "parameters" : [0, 0.5, 1], "arcLengthParameterization" : false });
        out = append(out, { "length" : roundToPrecision(evLength(context, { "entities" : edge }) / millimeter, 6),
                            "points" : mapArray(lines, function(l) { return round6(l.origin); }), "start" : dir6(lines[0].direction) });
    }
    return out;
}

// extrude: a 40 × 30 rectangle on the xy plane extruded 10 up
export function c001(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "r1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(s1);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "s1"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter, "oppositeDirection" : false });
    return { "edges" : edgeDirections(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID)) };
}

