    skRectangle(s1, "r1", { "firstCorner" : vector(10, 0) * millimeter, "secondCorner" : vector(20, 20) * millimeter });
    skSolve(s1);
    const axis = newSketchOnPlane(context, id + "axis", { "sketchPlane" : plane(vector(0, 0, -50) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(100, 0) * millimeter });
    skSolve(axis);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "s1"), "axis" : qCreatedBy(id + "axis", EntityType.EDGE), "fullRevolve" : false, "endBound" : RevolveBoundingType.BLIND, "angle" : 90 * degree, "oppositeDirection" : false });
    return { "edges" : edgeDirections(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID)) };
}

